diff --git a/flutter_app/lib/services/aiin_web_auth.dart b/flutter_app/lib/services/aiin_web_auth.dart
index 5e03df74ab..ebefee130b 100644
--- a/flutter_app/lib/services/aiin_web_auth.dart
+++ b/flutter_app/lib/services/aiin_web_auth.dart
@@ -7,6 +7,7 @@ import 'dart:async';
 import 'package:http/http.dart' as http;

 import 'package:fa/network/production_origins.dart';
+import 'package:fa/services/product_config_loader.dart';
 import 'package:fa/services/aiin_oauth_web_stub.dart'
     if (dart.library.html) 'package:fa/services/aiin_oauth_web_impl.dart';
 import 'package:flutter_agent_harness/flutter_agent_harness.dart';
@@ -15,6 +16,15 @@ import 'package:flutter_agent_harness/flutter_agent_harness.dart';
 /// (postMessage / BroadcastChannel / localStorage — see the page source).
 const aiinWebCallbackUrl = '$productionSiteOrigin/oauth/aiin.html';

+/// Branded hosts return the temporary code to their own registered callback;
+/// stock Fa retains the hosted callback for backward compatibility.
+String aiinOAuthCallbackForProduct(FaProductConfig config) =>
+    config.oauthCallback?.toString() ?? aiinWebCallbackUrl;
+
+/// Only a same-origin hosted callback may deliver the temporary OAuth code.
+bool acceptsAinOAuthMessageOrigin(String eventOrigin, String appOrigin) =>
+    eventOrigin.isNotEmpty && eventOrigin == appOrigin;
+
 /// One-click AIIN sign-in for the web build, mirroring the OpenRouter flow.
 /// The app opens the HOSTED AIIN sign-in page
 /// (`auth.aiin.by/login?client_redirect_uri=…&state=…`) in a named popup —
@@ -38,8 +48,10 @@ final class AiinWebAuthCoordinator {
     this.timeout = const Duration(minutes: 5),
   });

-  /// The shared coordinator with the Fa defaults.
-  static final instance = AiinWebAuthCoordinator();
+  /// The shared coordinator with the injected product's OAuth callback.
+  static final instance = AiinWebAuthCoordinator(
+    callbackUrl: aiinOAuthCallbackForProduct(loadInjectedProductConfig()),
+  );

   /// The redirect URI the hosted page redirects back to (allowlisted on
   /// the AIIN service).
diff --git a/flutter_app/test/aiin_web_auth_test.dart b/flutter_app/test/aiin_web_auth_test.dart
index 7eb72ff5d1..35cf345eb2 100644
--- a/flutter_app/test/aiin_web_auth_test.dart
+++ b/flutter_app/test/aiin_web_auth_test.dart
@@ -6,6 +6,7 @@ import 'dart:async';
 import 'dart:convert';

 import 'package:fa/services/aiin_web_auth.dart';
+import 'package:flutter_agent_harness/flutter_agent_harness.dart';
 import 'package:flutter_test/flutter_test.dart';
 import 'package:http/http.dart' as http;
 import 'package:http/testing.dart';
@@ -44,6 +45,44 @@ MockClient _mockBackend({int exchangeStatus = 200}) => MockClient(
     );

 void main() {
+  test('stock product retains the hosted AIIN callback', () {
+    expect(
+      aiinOAuthCallbackForProduct(FaProductConfig.stock),
+      'https://fa1.dev/oauth/aiin.html',
+    );
+  });
+
+  test('branded product uses its own registered AIIN callback', () {
+    final config = FaProductConfig(
+      productId: 'aiin',
+      displayName: 'AIIN Agent',
+      authEndpoint: Uri.parse('https://auth.aiin.by'),
+      oauthCallback: Uri.parse('https://www.aiin.by/agent/oauth/ain.html'),
+    );
+    expect(
+      aiinOAuthCallbackForProduct(config),
+      'https://www.aiin.by/agent/oauth/ain.html',
+    );
+  });
+
+  test('AIIN postMessage origin must exactly match the app origin', () {
+    expect(
+      acceptsAinOAuthMessageOrigin(
+        'https://www.aiin.by',
+        'https://www.aiin.by',
+      ),
+      isTrue,
+    );
+    expect(
+      acceptsAinOAuthMessageOrigin(
+        'https://attacker.example',
+        'https://www.aiin.by',
+      ),
+      isFalse,
+    );
+    expect(acceptsAinOAuthMessageOrigin('', ''), isFalse);
