  },
  'featureFlags': config.featureFlags.toList()..sort(),
  'driveAliases': config.driveAliases.toList()..sort(),
  'storageSchemaVersion': config.storageSchemaVersion,
};

Map<String, Object?> _manifest(FaProductConfig config) => {
